import{_ as l,a0 as o,w as r,s as d,I as s,x as n,a1 as i,A as p,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"如何在免费 WiFi 中保护隐私（四） | LCTT x X-CMD","titleTemplate":false,"description":"如何在免费 WiFi 中保护隐私（四） | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在免费 WiFi 中保护隐私（四） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在免费 WiFi 中保护隐私（四） | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210806 Access OpenVPN from a client computer","title":"如何在免费 WiFi 中保护隐私（四）","tag":"202108","desc":""},"relativePath":"202108/20210806 Access OpenVPN from a client computer.md","filePath":"[post].md"}'),g={name:"202108/20210806 Access OpenVPN from a client computer.md"};function u(f,e,k,h,m,b){const t=o("Link");return r(),d("div",null,[e[30]||(e[30]=s("h1",{id:"如何在免费-wifi-中保护隐私-四",tabindex:"-1"},[n("如何在免费 WiFi 中保护隐私（四） "),s("a",{class:"header-anchor",href:"#如何在免费-wifi-中保护隐私-四","aria-label":"Permalink to “如何在免费 WiFi 中保护隐私（四）”"},"​")],-1)),e[31]||(e[31]=s("blockquote",null,[s("p",null,"在 Linux 上安装好“虚拟专用网络” 之后，是时候使用它了。")],-1)),e[32]||(e[32]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/24/101214ng2afee2gmefgj5z.jpg",alt:""})],-1)),e[33]||(e[33]=s("p",null,"0penVPN 在两点之间创建了一个加密通道，以阻止第三方访问你的网络流量数据。通过设置你的 “虚拟专用网络” 服务，你可以成为你自己的 “虚拟专用网络” 服务商。许多流行的 “虚拟专用网络” 服务都使用 0penVPN，所以当你可以掌控自己的网络时，为什么还要将你的网络连接绑定到特定的提供商呢？",-1)),s("p",null,[e[3]||(e[3]=n("本系列的 ",-1)),i(t,{href:"https://linux.cn/article-13680-1.html"},{default:p(()=>[...e[0]||(e[0]=[n("第一篇文章",-1)])]),_:1}),e[4]||(e[4]=n(" 安装了一个“虚拟专用网络” 的服务器，",-1)),i(t,{href:"https://linux.cn/article-13702-1.html"},{default:p(()=>[...e[1]||(e[1]=[n("第二篇文章",-1)])]),_:1}),e[5]||(e[5]=n(" 介绍了如何安装和配置一个 0penVPN 服务软件，",-1)),i(t,{href:"https://linux.cn/article-13707-1.html"},{default:p(()=>[...e[2]||(e[2]=[n("第三篇文章",-1)])]),_:1}),e[6]||(e[6]=n(" 解释了如何配置防火墙并启动你的 0penVPN 服务。第四篇也是最后一篇文章将演示如何从客户端计算机使用你的 0penVPN 服务器。这就是你做了前三篇文章中所有工作的原因！",-1))]),e[34]||(e[34]=a(`<h3 id="创建客户端证书" tabindex="-1">创建客户端证书 <a class="header-anchor" href="#创建客户端证书" aria-label="Permalink to “创建客户端证书”">​</a></h3><p>请记住，0penVPN 的身份验证方法要求服务器和客户端都拥有某些东西（证书）并知道某些东西（口令）。是时候设置它了。</p><p>首先，为你的客户端计算机创建一个客户端证书和一个私钥。在你的 0penVPN 服务器上，生成证书请求。它会要求你输入密码；确保你记住它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  gen-req greglaptop</span></span></code></pre></div><p>本例中，<code>greglaptop</code> 是创建证书的客户端计算机主机名。</p><p>无需将请求导入证书颁发机构（CA），因为它已经存在。审查它以确保请求存在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  show-req greglaptop</span></span></code></pre></div><p>你也可以以客户端身份签署请求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  sign-req client greglaptop</span></span></code></pre></div><h3 id="安装-0penvpn-客户端软件" tabindex="-1">安装 0penVPN 客户端软件 <a class="header-anchor" href="#安装-0penvpn-客户端软件" aria-label="Permalink to “安装 0penVPN 客户端软件”">​</a></h3><p>在 Linux 系统上，网络管理器可能已经包含了一个 0penVPN 客户端。如果没有，你可以安装插件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install NetworkManager-openvpn</span></span></code></pre></div><p>在 Windows 系统上，你必须从 0penVPN 下载网页下载和安装 0penVPN 客户端。启动安装程序并按照提示操作。</p><h3 id="复制证书和私钥到客户端" tabindex="-1">复制证书和私钥到客户端 <a class="header-anchor" href="#复制证书和私钥到客户端" aria-label="Permalink to “复制证书和私钥到客户端”">​</a></h3>`,14)),s("p",null,[e[8]||(e[8]=n("现在你的客户端需要你为其生成的身份验证凭据。你在服务器上生成了这些，因此你必须将它们传输到你的客户端。我推荐使用 SSH 来完成传输。在 Linux 系统上，通过 ",-1)),e[9]||(e[9]=s("code",null,"scp",-1)),e[10]||(e[10]=n(" 命令实现。在 Windows 系统上，你可以以管理员身份运行 ",-1)),i(t,{href:"https://winscp.net/eng/index.php"},{default:p(()=>[...e[7]||(e[7]=[n("WinSCP",-1)])]),_:1}),e[11]||(e[11]=n(" 来推送证书和密钥。",-1))]),e[35]||(e[35]=a(`<p>假设客户端名称为 <code>greglaptop</code>，那么证书和私钥的文件名以及服务的位置如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/openvpn/ca/pki/issued/greglaptop.crt</span></span>
<span class="line"><span>/etc/openvpn/ca/pki/private/greglaptop.key</span></span>
<span class="line"><span>/etc/openvpn/ca/pki/issued/ca.crt</span></span></code></pre></div><p>在 Linux 系统上，复制这些文件到 <code>/etc/pki/tls/certs</code> 目录。在 Windows 系统上，复制它们到 <code>C:\\Program Files\\OpenVPN\\config</code> 目录。</p><h3 id="复制和自定义客户端配置文件" tabindex="-1">复制和自定义客户端配置文件 <a class="header-anchor" href="#复制和自定义客户端配置文件" aria-label="Permalink to “复制和自定义客户端配置文件”">​</a></h3><p>在 Linux 系统上，你可以复制服务器上的 <code>/etc/openvpn/client/OVPNclient2020.ovpn</code> 文件到 <code>/etc/NetworkManager/system-connections/</code> 目录，或者你也可以导航到系统设置中的网络管理器添加一个“虚拟专用网络” 连接。</p><p>连接类型选择“<ruby>证书（TLS）<rt>Certificates(TLS)</rt></ruby>”。告知网络管理器你从服务器上复制的证书和密钥。</p><p><img src="https://opensource.com/sites/default/files/uploads/network-manager-profile.jpg" alt="VPN displayed in Network Manager" title="VPN displayed in Network Manager"></p><p>在 Windows 系统上，以管理员身份运行 WinSCP，将服务器上的客户端配置模板 <code>/etc/openvpn/client/OVPNclient2020.ovpn</code> 文件复制到客户端上的 <code>C:\\Program Files\\OpenVPN\\config</code> 目录。然后：</p><ul><li>重命名它以匹配上面的证书。</li><li>更改 CA 证书、客户端证书和密钥的名称以匹配上面从服务器复制的名称。</li><li>修改 IP 信息，以匹配你的网络。</li></ul><p>你需要超级管理员权限来编辑客户端配置文件。最简单的方式就是以管理员身份启动一个 CMD 窗口，然后从管理员 CMD 窗口启动记事本来编辑此文件。</p><h3 id="将你的客户端连接到服务器" tabindex="-1">将你的客户端连接到服务器 <a class="header-anchor" href="#将你的客户端连接到服务器" aria-label="Permalink to “将你的客户端连接到服务器”">​</a></h3><p>在 Linux 系统上，网络管理器会显示你的 “虚拟专用网络” 连接。选择它进行连接。</p><p><img src="https://opensource.com/sites/default/files/uploads/network-manager-connect.jpg" alt="Add a connection in Network Manager" title="Add a“虚拟专用网络” connection in Network Manager"></p><p>在 Windows 系统上，启动 0penVPN 图形用户界面。它会在任务栏右侧的 Windows 系统托盘中生成一个图标，通常位于 Windows 桌面的右下角。右键单击图标以连接、断开连接或查看状态。</p><p>对于第一次连接，编辑客户端配置文件的 <code>remote</code> 行以使用 0penVPN 服务器的内部 IP 地址。通过右键单击 Windows 系统托盘中的 0penVPN 图标并单击“<ruby>连接<rt>Connect</rt></ruby>”，从办公室网络内部连接到服务器。调试此连接，这应该可以找到并解决问题，而不会出现任何防火墙问题，因为客户端和服务器都在防火墙的同一侧。</p><p>接下来，编辑客户端配置文件的 <code>remote</code> 行以使用 0penVPN 服务器的公共 IP 地址。将 Windows 客户端连接到外部网络并进行连接。调试有可能的问题。</p><h3 id="安全连接" tabindex="-1">安全连接 <a class="header-anchor" href="#安全连接" aria-label="Permalink to “安全连接”">​</a></h3><p>恭喜！你已经为其他客户端系统准备好了 0penVPN 网络。对其余客户端重复设置步骤。你甚至可以使用 Ansible 来分发证书和密钥并使其保持最新。</p>`,18)),s("p",null,[e[13]||(e[13]=n("本文基于 D.Greg Scott 的 ",-1)),i(t,{href:"https://www.dgregscott.com/how-to-build-a-vpn-in-four-easy-steps-without-spending-one-penny/"},{default:p(()=>[...e[12]||(e[12]=[n("博客",-1)])]),_:1}),e[14]||(e[14]=n("，经许可后重新使用。",-1))]),e[36]||(e[36]=s("hr",null,null,-1)),s("p",null,[e[16]||(e[16]=n("via: ",-1)),i(t,{href:"https://opensource.com/article/21/7/openvpn-client"},{default:p(()=>[...e[15]||(e[15]=[n("https://opensource.com/article/21/7/openvpn-client",-1)])]),_:1})]),s("p",null,[e[21]||(e[21]=n("作者：",-1)),i(t,{href:"https://opensource.com/users/greg-scott"},{default:p(()=>[...e[17]||(e[17]=[n("D. Greg Scott",-1)])]),_:1}),e[22]||(e[22]=n(" 选题：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:p(()=>[...e[18]||(e[18]=[n("lujun9972",-1)])]),_:1}),e[23]||(e[23]=n(" 译者：",-1)),i(t,{href:"https://github.com/perfiffer"},{default:p(()=>[...e[19]||(e[19]=[n("perfiffer",-1)])]),_:1}),e[24]||(e[24]=n(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[20]||(e[20]=[n("wxy",-1)])]),_:1})]),s("p",null,[e[27]||(e[27]=n("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[25]||(e[25]=[n("LCTT",-1)])]),_:1}),e[28]||(e[28]=n(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:p(()=>[...e[26]||(e[26]=[n("Linux中国",-1)])]),_:1}),e[29]||(e[29]=n(" 荣誉推出",-1))])])}const C=l(g,[["render",u]]);export{N as __pageData,C as default};
